def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change_ratio = (v2 - v1) / v1
    percentage_growth = change_ratio * 100

    return {
        "value": percentage_growth,
        "trace": {
            "initial_value": v1,
            "final_value": v2,
            "change": v2 - v1,
            "change_ratio": change_ratio,
            "percentage_growth": percentage_growth,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
